const SHARED_QUESTIONS = [
{"id": "sec-001", "section": "8.1", "type": "desc", "question": "暗号化とは？", "answer": "平文を鍵を使って第三者に読めない暗号文に変換すること。元に戻すことを復号という。", "explanation": "盗聴されても内容を知られないようにする（機密性の確保）。", "createdAt": 1791810000001},
{"id": "sec-002", "section": "8.1", "type": "desc", "question": "共通鍵暗号方式とは？", "answer": "暗号化と復号に同じ鍵（共通鍵）を使う方式。送信者と受信者で鍵を秘密に共有する。", "explanation": "秘密鍵暗号方式・対称鍵暗号方式とも呼ぶ。", "createdAt": 1791810000002},
{"id": "sec-003", "section": "8.1", "type": "desc", "question": "共通鍵暗号方式の特徴は？", "answer": "処理が速く、大量データの暗号化に向く。一方で、鍵を安全に相手へ渡す必要があり（鍵配送問題）、通信相手ごとに鍵が必要なので鍵の管理が大変。", "explanation": "", "createdAt": 1791810000003},
{"id": "sec-004", "section": "8.1", "type": "desc", "question": "共通鍵暗号方式で n 人が互いに通信するのに必要な鍵の数は？", "answer": "n(n−1)/2 個", "explanation": "例：10人なら45個。公開鍵暗号方式なら 2n 個（10人で20個）。", "createdAt": 1791810000004},
{"id": "sec-005", "section": "8.1", "type": "desc", "question": "DES とは？", "answer": "Data Encryption Standard＝データ暗号化標準。米国で標準化された共通鍵暗号方式（ブロック長64ビット、鍵長56ビット）。鍵長が短く、現在は安全でない。", "explanation": "DESを3回繰り返すトリプルDES（3DES）も使われたが、現在はAESへの移行が推奨されている。", "createdAt": 1791810000005},
{"id": "sec-006", "section": "8.1", "type": "desc", "question": "AES とは？", "answer": "Advanced Encryption Standard＝高度暗号化標準。DESの後継となる米国標準の共通鍵暗号方式。ブロック長128ビット、鍵長は128／192／256ビットから選べる。", "explanation": "無線LAN（WPA2・WPA3）やTLSなどで広く使われる。", "createdAt": 1791810000006},
{"id": "sec-007", "section": "8.1", "type": "desc", "question": "公開鍵暗号方式とは？", "answer": "暗号化と復号で異なる鍵（公開鍵と秘密鍵のペア）を使う方式。受信者の公開鍵で暗号化し、受信者だけが持つ秘密鍵で復号する。", "explanation": "非対称鍵暗号方式とも呼ぶ。デジタル署名では逆に、送信者の秘密鍵で署名し、送信者の公開鍵で検証する。", "createdAt": 1791810000007},
{"id": "sec-008", "section": "8.1", "type": "desc", "question": "公開鍵暗号方式の特徴は？", "answer": "公開鍵は公開してよいので鍵配送問題が解決し、鍵の管理が容易。一方で処理が遅く、大量データの暗号化には向かない。", "explanation": "公開鍵が本当に本人のものかを保証するために、PKI（デジタル証明書）が必要になる。", "createdAt": 1791810000008},
{"id": "sec-009", "section": "8.1", "type": "desc", "question": "公開鍵暗号方式で n 人が互いに通信するのに必要な鍵の数は？", "answer": "2n 個（1人につき公開鍵と秘密鍵の1組）", "explanation": "", "createdAt": 1791810000009},
{"id": "sec-010", "section": "8.1", "type": "desc", "question": "量子暗号とは？", "answer": "光子などの量子の性質を利用した暗号技術。量子鍵配送（QKD）では、盗聴されると量子の状態が変化するため、盗聴を検知できる。", "explanation": "量子コンピュータでも破られない安全性が期待される。量子コンピュータに耐える従来型の暗号は耐量子計算機暗号（PQC）と呼んで区別する。", "createdAt": 1791810000010},
{"id": "sec-011", "section": "8.1", "type": "desc", "question": "RSA とは？", "answer": "Rivest-Shamir-Adleman（考案者3人の頭文字）。大きな数の素因数分解が難しいことを安全性の根拠とする公開鍵暗号方式。暗号化とデジタル署名に使える。", "explanation": "安全性を保つため、鍵長を長く（2048ビット以上）する必要がある。", "createdAt": 1791810000011},
{"id": "sec-012", "section": "8.1", "type": "desc", "question": "楕円曲線暗号とは？", "answer": "楕円曲線上の離散対数問題が難しいことを安全性の根拠とする公開鍵暗号方式。RSAより短い鍵長で同じ程度の安全性が得られ、処理が軽い。", "explanation": "ECC（Elliptic Curve Cryptography）。署名方式のECDSA、鍵交換のECDHなど。ICカードやスマートフォンに向く。", "createdAt": 1791810000012},
{"id": "sec-013", "section": "8.1", "type": "desc", "question": "エルガマル暗号とは？", "answer": "離散対数問題が難しいことを安全性の根拠とする公開鍵暗号方式。", "explanation": "暗号化に乱数を使うため、同じ平文でも暗号化のたびに異なる暗号文になる。暗号文の長さは平文の約2倍になる。", "createdAt": 1791810000013},
{"id": "sec-014", "section": "8.1", "type": "desc", "question": "ハイブリッド暗号方式とは？", "answer": "共通鍵暗号方式と公開鍵暗号方式を組み合わせた方式。データは高速な共通鍵で暗号化し、その共通鍵を受信者の公開鍵で暗号化して送る。", "explanation": "", "createdAt": 1791810000014},
{"id": "sec-015", "section": "8.1", "type": "desc", "question": "ハイブリッド暗号方式の特徴は？", "answer": "共通鍵暗号の「処理の速さ」と、公開鍵暗号の「鍵配送の容易さ」の両方の長所を生かせる。", "explanation": "TLS、S/MIME、PGPなどで使われている。", "createdAt": 1791810000015},
{"id": "sec-016", "section": "8.2", "type": "desc", "question": "WEP とは？", "answer": "Wired Equivalent Privacy＝有線同等機密。初期の無線LANの暗号化方式で、暗号アルゴリズムにRC4を使う。", "explanation": "", "createdAt": 1791810000016},
{"id": "sec-017", "section": "8.2", "type": "desc", "question": "WEPの特徴は？", "answer": "全端末で同じ固定のWEPキーを使い、24ビットのIVと組み合わせてRC4で暗号化する。鍵は自動では更新されない。", "explanation": "", "createdAt": 1791810000017},
{"id": "sec-018", "section": "8.2", "type": "desc", "question": "WEPが現在使われていない理由は？", "answer": "IVが24ビットと短く同じ値が繰り返し使われることや、RC4の弱点により、短時間でWEPキーを解読できる脆弱性が見つかったため。", "explanation": "現在はWPA2・WPA3を使う。", "createdAt": 1791810000018},
{"id": "sec-019", "section": "8.2", "type": "desc", "question": "IV とは？（無線LANの暗号）", "answer": "Initialization Vector＝初期化ベクトル。暗号化のたびに変える値で、鍵と組み合わせて使い、同じ鍵・同じ平文でも異なる暗号文にする。", "explanation": "WEPでは24ビットと短く、値の重複が解読の原因になった。", "createdAt": 1791810000019},
{"id": "sec-020", "section": "8.2", "type": "desc", "question": "WEPキーとは？", "answer": "WEPでアクセスポイントと端末が共有する固定の暗号鍵（40ビットまたは104ビット）。IVと連結してRC4の鍵にする。", "explanation": "", "createdAt": 1791810000020},
{"id": "sec-021", "section": "8.2", "type": "desc", "question": "RC4 とは？", "answer": "Rivest Cipher 4。1バイトずつ暗号化するストリーム暗号方式の共通鍵暗号。WEPやWPA（TKIP）、かつてのSSL/TLSで使われたが、脆弱性があり現在は使用禁止・非推奨。", "explanation": "", "createdAt": 1791810000021},
{"id": "sec-022", "section": "8.2", "type": "desc", "question": "WPA とは？", "answer": "Wi-Fi Protected Access。WEPの脆弱性を補うためにWi-Fi Allianceが定めた無線LANのセキュリティ規格。暗号化にTKIPを使う。", "explanation": "", "createdAt": 1791810000022},
{"id": "sec-023", "section": "8.2", "type": "desc", "question": "WPAの特徴は？", "answer": "WEPと同じRC4を使いながら、TKIPで鍵を一定時間ごとに自動更新し、IVを48ビットに広げて安全性を高めた。WEP用の機器でもファームウェアの更新で対応できた。", "explanation": "現在はTKIPも脆弱とされ、WPA2・WPA3が推奨される。", "createdAt": 1791810000023},
{"id": "sec-024", "section": "8.2", "type": "desc", "question": "TKIP とは？", "answer": "Temporal Key Integrity Protocol。WPAで使う暗号化プロトコル。暗号アルゴリズムはRC4のままで、パケットごとに鍵を変え、一定時間ごとに鍵を更新する。", "explanation": "", "createdAt": 1791810000024},
{"id": "sec-025", "section": "8.2", "type": "desc", "question": "WPA2 とは？", "answer": "Wi-Fi Protected Access 2。IEEE 802.11iに準拠した無線LANのセキュリティ規格。暗号化方式にAESベースのCCMPを必須とする。", "explanation": "", "createdAt": 1791810000025},
{"id": "sec-026", "section": "8.2", "type": "desc", "question": "WPA2の特徴は？", "answer": "暗号化にAES（CCMP）を使い、WPAより安全性が高い。認証方式にパーソナルモード（PSK）とエンタープライズモード（IEEE 802.1X）がある。", "explanation": "2017年にKRACKs（鍵再インストール攻撃）という脆弱性が見つかった。", "createdAt": 1791810000026},
{"id": "sec-027", "section": "8.2", "type": "desc", "question": "CCMP とは？", "answer": "Counter mode with CBC-MAC Protocol。WPA2で使うAESベースの暗号化プロトコル。暗号化（CTRモード）と改ざんの検知（CBC-MAC）を行う。", "explanation": "", "createdAt": 1791810000027},
{"id": "sec-028", "section": "8.2", "type": "desc", "question": "AES-CCMP とは？", "answer": "暗号アルゴリズムにAESを使ったCCMPのこと。WPA2・WPA3の暗号化方式。", "explanation": "", "createdAt": 1791810000028},
{"id": "sec-029", "section": "8.2", "type": "desc", "question": "WPA3 とは？", "answer": "Wi-Fi Protected Access 3。2018年に策定されたWPA2の後継規格。パーソナルモードの認証にSAEを採用した。", "explanation": "", "createdAt": 1791810000029},
{"id": "sec-030", "section": "8.2", "type": "desc", "question": "WPA3の特徴は？", "answer": "パーソナルモードではSAE（Simultaneous Authentication of Equals）で鍵を交換するため、辞書攻撃（オフラインでの総当たり）に強く、前方秘匿性もある。エンタープライズモードでは192ビットセキュリティモード（CNSA準拠）を選べる。", "explanation": "", "createdAt": 1791810000030},
{"id": "sec-031", "section": "8.2", "type": "desc", "question": "前方秘匿性とは？", "answer": "Forward Secrecy。長く使う鍵（秘密鍵やパスワード）が将来漏えいしても、過去の通信の暗号文は解読されないという性質。セッションごとに使い捨ての鍵を作ることで実現する。", "explanation": "PFS（Perfect Forward Secrecy）とも呼ぶ。TLS1.3では必須。", "createdAt": 1791810000031},
{"id": "sec-032", "section": "8.2", "type": "desc", "question": "CNSA とは？", "answer": "Commercial National Security Algorithm Suite＝商用国家安全保障アルゴリズム。米国NSAが定めた、機密情報を守るための暗号アルゴリズムの組み合わせ。WPA3エンタープライズの192ビットモードで使う。", "explanation": "", "createdAt": 1791810000032},
{"id": "sec-033", "section": "8.2", "type": "desc", "question": "パーソナルモードとは？（無線LAN）", "answer": "家庭や小規模向けの認証方式。アクセスポイントと端末に同じ事前共有鍵（パスフレーズ）を設定して認証する。", "explanation": "WPA2ではPSK、WPA3ではSAEを使う。", "createdAt": 1791810000033},
{"id": "sec-034", "section": "8.2", "type": "desc", "question": "PSK とは？", "answer": "Pre-Shared Key＝事前共有鍵。アクセスポイントと端末にあらかじめ同じ鍵（パスフレーズ）を設定しておく方式。", "explanation": "パスフレーズが漏れると、同じ鍵を使う全端末に影響する。", "createdAt": 1791810000034},
{"id": "sec-035", "section": "8.2", "type": "desc", "question": "エンタープライズモードとは？（無線LAN）", "answer": "企業向けの認証方式。IEEE 802.1XとRADIUSサーバを使い、利用者ごとのID・パスワードやデジタル証明書で認証する。", "explanation": "", "createdAt": 1791810000035},
{"id": "sec-036", "section": "8.2", "type": "desc", "question": "IEEE 802.1X とは？", "answer": "LANに接続する端末を利用者単位で認証する規格。端末（サプリカント）、スイッチやアクセスポイント（オーセンティケータ）、認証サーバ（RADIUSサーバ）で構成し、認証にはEAPを使う。", "explanation": "有線LANでも無線LANでも使える。", "createdAt": 1791810000036},
{"id": "sec-037", "section": "8.2", "type": "desc", "question": "PMK とは？", "answer": "Pairwise Master Key＝ペアワイズマスター鍵。無線LANで、端末とアクセスポイントの間の暗号鍵を作る元になる鍵。パーソナルモードではパスフレーズから、エンタープライズモードでは802.1X認証の結果から作られる。", "explanation": "", "createdAt": 1791810000037},
{"id": "sec-038", "section": "8.3", "type": "desc", "question": "アクセスコントロールとは？", "answer": "利用者を識別・認証し、許可された人だけが、許可された範囲で情報資源を使えるように制御すること。アクセス制御。", "explanation": "識別（誰か）→ 認証（本人か）→ 認可（何をしてよいか）の順に行う。", "createdAt": 1791810000038},
{"id": "sec-039", "section": "8.3", "type": "desc", "question": "認証システムとは？", "answer": "利用者が本人であることを確認する仕組み。知識（パスワード）、所持（ICカード・スマートフォン）、生体（指紋・顔）の情報を使う。", "explanation": "", "createdAt": 1791810000039},
{"id": "sec-040", "section": "8.3", "type": "desc", "question": "認証とは？", "answer": "相手が本人（正当なもの）であることを確かめること。利用者認証のほか、メッセージ認証（改ざんされていないか）、サーバ認証などがある。", "explanation": "", "createdAt": 1791810000040},
{"id": "sec-041", "section": "8.3", "type": "desc", "question": "権限管理とは？", "answer": "認証した利用者に、どの資源に対してどの操作（参照・更新・削除など）を許すかを決めて管理すること。", "explanation": "必要最小限の権限だけを与える「最小権限の原則」が基本。", "createdAt": 1791810000041},
{"id": "sec-042", "section": "8.3", "type": "desc", "question": "固定式パスワード方式とは？", "answer": "利用者があらかじめ登録した同じパスワードを、毎回使って認証する方式。手軽だが、盗聴・推測・使い回しで不正利用されやすい。", "explanation": "", "createdAt": 1791810000042},
{"id": "sec-043", "section": "8.3", "type": "desc", "question": "パスワードの理論的な総数は？（文字の種類 n、桁数 k）", "answer": "n の k 乗（n^k）通り", "explanation": "例：英小文字26種類で8桁なら 26^8 ≒ 約2,088億通り。文字の種類と桁数を増やすほど、総当たり攻撃に時間がかかる。", "createdAt": 1791810000043},
{"id": "sec-044", "section": "8.3", "type": "desc", "question": "チャレンジレスポンス認証とは？", "answer": "サーバが毎回異なる乱数（チャレンジ）を送り、クライアントはパスワードとチャレンジからハッシュ値（レスポンス）を計算して返す認証方式。パスワードそのものはネットワークを流れない。", "explanation": "チャレンジが毎回変わるので、盗聴したレスポンスを再利用するリプレイ攻撃に強い。", "createdAt": 1791810000044},
{"id": "sec-045", "section": "8.3", "type": "desc", "question": "スニッフィングとは？", "answer": "ネットワークを流れるパケットを盗聴して、パスワードなどの情報を盗み取ること。", "explanation": "", "createdAt": 1791810000045},
{"id": "sec-046", "section": "8.3", "type": "desc", "question": "PPP とは？", "answer": "Point-to-Point Protocol＝ポイントツーポイントプロトコル。2点間を接続するデータリンク層のプロトコル。認証方式としてPAPやCHAPを使う。", "explanation": "", "createdAt": 1791810000046},
{"id": "sec-047", "section": "8.3", "type": "desc", "question": "CHAP とは？", "answer": "Challenge Handshake Authentication Protocol＝チャレンジハンドシェイク認証プロトコル。PPPで使うチャレンジレスポンス方式の認証。パスワードを平文で送らない。", "explanation": "PAPはパスワードを平文で送るため、盗聴に弱い。", "createdAt": 1791810000047},
{"id": "sec-048", "section": "8.3", "type": "desc", "question": "チャレンジコードとは？", "answer": "チャレンジレスポンス認証で、サーバが認証のたびに作ってクライアントに送る乱数。", "explanation": "", "createdAt": 1791810000048},
{"id": "sec-049", "section": "8.3", "type": "desc", "question": "ハッシュ関数とは？", "answer": "任意の長さのデータから、固定長の値（ハッシュ値）を求める関数。ハッシュ値から元のデータを求められない（原像計算困難性＝不可逆関数）、同じハッシュ値になる別のデータを見つけるのが難しい（衝突発見困難性）という性質を持つ。", "explanation": "改ざんの検知、パスワードの保存、デジタル署名に使う。", "createdAt": 1791810000049},
{"id": "sec-050", "section": "8.3", "type": "desc", "question": "ハッシュ値とは？", "answer": "ハッシュ関数で求めた固定長の値。元のデータが1ビットでも変わると、まったく違う値になる。", "explanation": "メッセージダイジェストとも呼ぶ。", "createdAt": 1791810000050},
{"id": "sec-051", "section": "8.3", "type": "desc", "question": "ワンタイムパスワードとは？", "answer": "1回しか使えない使い捨てのパスワード。盗聴されても次回は使えないため、リプレイ攻撃に強い。", "explanation": "作り方に、時刻同期方式、チャレンジレスポンス方式、S/KEY方式などがある。", "createdAt": 1791810000051},
{"id": "sec-052", "section": "8.3", "type": "desc", "question": "時刻同期方式とは？（ワンタイムパスワード）", "answer": "トークン（専用機器やスマートフォンのアプリ）と認証サーバが、同じ時刻と秘密情報からパスワードを作り、一定時間（30秒など）ごとに変わるパスワードで認証する方式。", "explanation": "TOTPが代表例。トークンとサーバの時刻がずれていると認証できない。", "createdAt": 1791810000052},
{"id": "sec-053", "section": "8.3", "type": "desc", "question": "S/KEY方式とは？", "answer": "ワンタイムパスワードの方式の一つ。パスワードにハッシュ関数を繰り返しかけた値の列を作り、かけた回数の多いものから逆順に1つずつ使う。サーバはチャレンジ（シーケンス番号とシード）を送り、クライアントが計算して返す。", "explanation": "ハッシュ関数は元に戻せないので、使った値から次に使う値を推測できない。", "createdAt": 1791810000053},
{"id": "sec-054", "section": "8.3", "type": "desc", "question": "シングルサインオン（SSO）とは？", "answer": "1回の認証で、複数のシステムやサービスを、改めてログインせずに使えるようにする仕組み。", "explanation": "実現方式に、クッキー型、リバースプロキシ型、SAML型などがある。便利だが、認証情報が漏れると被害がすべてのサービスに及ぶ。", "createdAt": 1791810000054},
{"id": "sec-055", "section": "8.3", "type": "desc", "question": "クッキー型（シングルサインオン）とは？", "answer": "認証サーバが、認証済みであることを示す情報をクッキーとして利用者のブラウザに発行し、各サーバがそのクッキーを確認する方式。", "explanation": "クッキーはドメインをまたいで送れないため、同じドメインのサーバの間に限られる。", "createdAt": 1791810000055},
{"id": "sec-056", "section": "8.3", "type": "desc", "question": "リバースプロキシ型（シングルサインオン）とは？", "answer": "利用者が必ずリバースプロキシサーバを経由して各サーバにアクセスし、リバースプロキシサーバがまとめて認証する方式。", "explanation": "各サーバを改修しなくてよいが、アクセスが集中し、リバースプロキシが単一障害点になりやすい。", "createdAt": 1791810000056},
{"id": "sec-057", "section": "8.3", "type": "desc", "question": "リバースプロキシサーバとは？", "answer": "Webサーバの手前に置き、外部からのアクセスを代わりに受けてWebサーバへ中継するサーバ。負荷分散、認証、キャッシュ、TLSの処理、Webサーバを直接公開しないための対策などに使う。", "explanation": "内部から外部へのアクセスを代わりに行うのはフォワードプロキシ。", "createdAt": 1791810000057},
{"id": "sec-058", "section": "8.3", "type": "desc", "question": "SAML型（シングルサインオン）とは？", "answer": "SAML（Security Assertion Markup Language、XMLベースの標準）を使い、IdPが発行した認証結果（アサーション）をSPが受け取って利用者を認証する方式。ドメインの異なるサービスの間でもシングルサインオンできる。", "explanation": "クラウドサービスのシングルサインオンで多く使われる。", "createdAt": 1791810000058},
{"id": "sec-059", "section": "8.3", "type": "desc", "question": "SP（Service Provider）とは？（SAML）", "answer": "サービス提供者。利用者が使いたいサービス（Webアプリケーションなど）を提供し、認証はIdPに任せて、その結果を信頼する側。", "explanation": "", "createdAt": 1791810000059},
{"id": "sec-060", "section": "8.3", "type": "desc", "question": "IdP とは？ また SP-Initiated とは？", "answer": "IdP（Identity Provider）＝ID提供者。利用者を認証し、認証結果（アサーション）をSPに発行する。SP-Initiatedは、利用者がまずSPにアクセスし、未認証ならSPがIdPへ転送して認証させ、IdPのアサーションを持ってSPに戻る流れ。", "explanation": "先にIdPにログインしてから使うSPを選ぶ流れは IdP-Initiated という。", "createdAt": 1791810000060},
{"id": "sec-061", "section": "8.3", "type": "desc", "question": "Keycloak とは？", "answer": "オープンソースのID管理・アクセス管理ソフトウェア。IdPとして使え、SAML、OpenID Connect、OAuth 2.0 に対応してシングルサインオンを実現できる。", "explanation": "", "createdAt": 1791810000061},
{"id": "sec-062", "section": "8.3", "type": "desc", "question": "バイオメトリクス認証とは？", "answer": "指紋・顔・静脈・虹彩・声紋・筆跡など、本人の身体的な特徴や行動の特徴を使う認証。生体認証。忘れたり紛失したりしない。", "explanation": "生体情報は変更できないため、漏えいしたときの影響が大きい。", "createdAt": 1791810000062},
{"id": "sec-063", "section": "8.3", "type": "desc", "question": "バイオメトリクス認証の種類は？", "answer": "身体的な特徴を使うもの（指紋、顔、静脈、虹彩、網膜、掌形）と、行動の特徴を使うもの（声紋、筆跡（署名の書き方）、キーストローク、歩き方）がある。", "explanation": "", "createdAt": 1791810000063},
{"id": "sec-064", "section": "8.3", "type": "desc", "question": "FRR と FAR とは？（バイオメトリクス認証）", "answer": "FRR（False Rejection Rate＝本人拒否率）は、本人なのに拒否してしまう割合。FAR（False Acceptance Rate＝他人受入率）は、他人を本人と誤って受け入れる割合。判定を厳しくするとFARは下がるがFRRは上がる（トレードオフ）。", "explanation": "安全性を重視するならFARを下げ、利便性を重視するならFRRを下げる。", "createdAt": 1791810000064},
{"id": "sec-065", "section": "8.3", "type": "desc", "question": "リスクベース認証とは？", "answer": "いつもと違う環境（IPアドレス、端末、時間帯、場所など）からのログインのときだけ、合言葉やワンタイムパスワードなどの追加の認証を行う方式。", "explanation": "利便性を保ちながら、パスワードを盗まれたときの不正ログインを防ぐ。", "createdAt": 1791810000065},
{"id": "sec-066", "section": "8.3", "type": "desc", "question": "Kerberos方式とは？", "answer": "認証サーバ（KDC）が発行するチケットを使って、1回の認証で複数のサーバを使えるようにする認証方式。共通鍵暗号を使い、パスワードはネットワークに流さない。", "explanation": "チケットに有効期限があるため、サーバとクライアントの時刻を合わせておく必要がある。Windowsのドメイン認証（Active Directory）で使われる。", "createdAt": 1791810000066},
{"id": "sec-067", "section": "8.3", "type": "desc", "question": "多要素認証とは？", "answer": "知識情報（パスワード）、所持情報（スマートフォン・ICカード）、生体情報（指紋・顔）のうち、異なる2種類以上を組み合わせる認証。", "explanation": "パスワードを2回入れるなど、同じ種類を重ねるのは多要素ではなく多段階認証。", "createdAt": 1791810000067},
{"id": "sec-068", "section": "8.3", "type": "desc", "question": "CAPTCHA認証とは？", "answer": "Completely Automated Public Turing test to tell Computers and Humans Apart＝コンピュータと人間を区別する完全自動化された公開チューリングテスト。ゆがんだ文字の読み取りや画像の選択をさせ、操作しているのが人間かプログラム（ボット）かを判定する。", "explanation": "ボットによるアカウントの大量登録や総当たり攻撃を防ぐ。", "createdAt": 1791810000068},
{"id": "sec-069", "section": "8.3", "type": "desc", "question": "多要素認証疲労攻撃とは？", "answer": "盗んだパスワードでログインを試み、利用者のスマートフォンに多要素認証の承認要求（プッシュ通知）を大量に送りつけ、利用者が根負けや誤操作で承認するのを狙う攻撃。MFA疲労攻撃、MFAボミングともいう。", "explanation": "対策は、画面に出た番号を入力させる番号照合（ナンバーマッチング）など。", "createdAt": 1791810000069},
{"id": "sec-070", "section": "8.3", "type": "desc", "question": "RADIUS とは？", "answer": "Remote Authentication Dial In User Service。ネットワークに接続する利用者の認証・認可・アカウンティング（利用記録）を一元管理するためのプロトコル。IEEE 802.1Xの認証サーバとして使われる。", "explanation": "認証（Authentication）・認可（Authorization）・アカウンティング（Accounting）の頭文字でAAAという。", "createdAt": 1791810000070},
{"id": "sec-071", "section": "8.3", "type": "desc", "question": "Diameter とは？", "answer": "RADIUSの後継となる、認証・認可・アカウンティング（AAA）のプロトコル。信頼性の高いTCPやSCTPを使い、携帯電話網（LTEなど）で使われる。", "explanation": "名前はRADIUS（半径）の2倍＝Diameter（直径）にかけたもの。", "createdAt": 1791810000071},
{"id": "sec-072", "section": "8.3", "type": "desc", "question": "EAP とは？", "answer": "Extensible Authentication Protocol＝拡張可能な認証プロトコル。PPPの認証を拡張したプロトコルで、さまざまな認証方式を選んで使える。IEEE 802.1Xで使う。", "explanation": "", "createdAt": 1791810000072},
{"id": "sec-073", "section": "8.3", "type": "desc", "question": "EAP-TLS とは？", "answer": "EAPの認証方式の一つ。サーバとクライアント（端末）の両方がデジタル証明書を使って、互いに認証する。安全性が高い。", "explanation": "", "createdAt": 1791810000073},
{"id": "sec-074", "section": "8.3", "type": "desc", "question": "EAP-MD5 とは？", "answer": "EAPの認証方式の一つ。ユーザIDとパスワードを使い、MD5でチャレンジレスポンス認証を行う。クライアント側だけを認証し、サーバを認証しないため、安全性は低い。", "explanation": "", "createdAt": 1791810000074},
{"id": "sec-075", "section": "8.4", "type": "desc", "question": "デジタル署名とは？", "answer": "送信者が自分の秘密鍵でメッセージダイジェストを暗号化（署名）し、受信者が送信者の公開鍵で検証する仕組み。送信者が本人であること（なりすましがないこと）と、改ざんされていないことを確認できる。", "explanation": "公開鍵暗号方式の鍵の使い方が、暗号化のときと逆になる。", "createdAt": 1791810000075},
{"id": "sec-076", "section": "8.4", "type": "desc", "question": "否認防止とは？", "answer": "ある行為をした人が、後から「自分はしていない」と否定できないようにすること。デジタル署名やログの記録で実現する。", "explanation": "情報セキュリティの7要素（機密性・完全性・可用性・真正性・責任追跡性・否認防止・信頼性）の一つ。", "createdAt": 1791810000076},
{"id": "sec-077", "section": "8.4", "type": "desc", "question": "署名生成と署名検証の手順は？", "answer": "【署名生成】送信者は、メッセージのハッシュ値（メッセージダイジェスト）を求め、自分の秘密鍵で暗号化して署名とし、メッセージに付けて送る。【署名検証】受信者は、署名を送信者の公開鍵で復号し、受け取ったメッセージから求めたハッシュ値と一致すれば、本人からのもので改ざんもないと判断する。", "explanation": "", "createdAt": 1791810000077},
{"id": "sec-078", "section": "8.4", "type": "desc", "question": "メッセージダイジェストとは？", "answer": "メッセージをハッシュ関数にかけて得られる固定長の値（ハッシュ値）。メッセージの要約。改ざんの検知やデジタル署名に使う。", "explanation": "", "createdAt": 1791810000078},
{"id": "sec-079", "section": "8.4", "type": "desc", "question": "MD5 とは？", "answer": "Message Digest Algorithm 5。128ビットのハッシュ値を作るハッシュ関数。衝突（同じハッシュ値になる別のデータ）を見つける攻撃が見つかっていて、現在は安全でない。", "explanation": "", "createdAt": 1791810000079},
{"id": "sec-080", "section": "8.4", "type": "desc", "question": "SHA-1 とは？", "answer": "Secure Hash Algorithm 1。160ビットのハッシュ値を作るハッシュ関数。衝突攻撃が成功していて、現在はデジタル署名などでの利用は推奨されない。", "explanation": "", "createdAt": 1791810000080},
{"id": "sec-081", "section": "8.4", "type": "desc", "question": "SHA-2 とは？", "answer": "Secure Hash Algorithm 2。SHA-1の後継となるハッシュ関数の総称。SHA-224、SHA-256、SHA-384、SHA-512、SHA-512/224、SHA-512/256 がある。", "explanation": "数字はハッシュ値のビット数。現在広く使われている。", "createdAt": 1791810000081},
{"id": "sec-082", "section": "8.4", "type": "desc", "question": "SHA-3 とは？", "answer": "Secure Hash Algorithm 3。SHA-2とは異なる内部構造（Keccak、スポンジ構造）を持つハッシュ関数。SHA-2に問題が見つかったときの代わりとして標準化された。", "explanation": "", "createdAt": 1791810000082},
{"id": "sec-083", "section": "8.4", "type": "desc", "question": "SHA-256 とは？", "answer": "SHA-2の一つで、256ビットのハッシュ値を作る。デジタル証明書やブロックチェーン（ビットコイン）などで広く使われる。", "explanation": "", "createdAt": 1791810000083},
{"id": "sec-084", "section": "8.4", "type": "desc", "question": "SHA-512/256 とは？", "answer": "SHA-2の一つ。SHA-512と同じ計算（64ビット単位の処理）を行い、結果を256ビットに切り詰めて出力する。64ビットCPUではSHA-256より速いことがある。", "explanation": "初期値がSHA-512と異なるため、SHA-512の結果の先頭256ビットとは別の値になる。", "createdAt": 1791810000084},
{"id": "sec-085", "section": "8.4", "type": "desc", "question": "PKI とは？", "answer": "Public Key Infrastructure＝公開鍵基盤。認証局がデジタル証明書を発行し、公開鍵が本人のものであることを保証する仕組み全体。", "explanation": "", "createdAt": 1791810000085},
{"id": "sec-086", "section": "8.4", "type": "desc", "question": "認証局（CA）とは？", "answer": "Certification Authority。公開鍵とその持ち主を結びつけるデジタル証明書を発行・失効させる第三者機関。証明書には、認証局が自分の秘密鍵でデジタル署名する。", "explanation": "最上位の認証局をルート認証局という。", "createdAt": 1791810000086},
{"id": "sec-087", "section": "8.4", "type": "desc", "question": "デジタル証明書（公開鍵証明書）とは？", "answer": "公開鍵とその持ち主の情報を結びつけ、認証局がデジタル署名した電子的な証明書。規格はX.509。持ち主の情報、公開鍵、有効期間、発行者、認証局の署名などを含む。", "explanation": "秘密鍵は含まない。", "createdAt": 1791810000087},
{"id": "sec-088", "section": "8.4", "type": "desc", "question": "RA とは？（PKI）", "answer": "Registration Authority＝登録局。証明書の発行を申請した人の本人確認と、申請の受付・審査を行う。", "explanation": "", "createdAt": 1791810000088},
{"id": "sec-089", "section": "8.4", "type": "desc", "question": "IA とは？（PKI）", "answer": "Issuing Authority＝発行局。RAの審査結果にもとづいて、デジタル証明書を実際に発行・失効させる。", "explanation": "", "createdAt": 1791810000089},
{"id": "sec-090", "section": "8.4", "type": "desc", "question": "VA とは？（PKI）", "answer": "Validation Authority＝検証局。証明書が失効していないかなど、証明書の有効性を確認して答える。OCSPレスポンダがこれにあたる。", "explanation": "", "createdAt": 1791810000090},
{"id": "sec-091", "section": "8.4", "type": "desc", "question": "CP とは？（PKI）", "answer": "Certificate Policy＝証明書ポリシ。認証局が発行する証明書の用途や信頼性の水準など、証明書の運用に関する方針を定めた文書。", "explanation": "", "createdAt": 1791810000091},
{"id": "sec-092", "section": "8.4", "type": "desc", "question": "CPS とは？（PKI）", "answer": "Certification Practice Statement＝認証実施規程。CPに従って、認証局が証明書を具体的にどのように発行・管理・失効させるかを定めた文書。", "explanation": "", "createdAt": 1791810000092},
{"id": "sec-093", "section": "8.4", "type": "desc", "question": "CRL とは？", "answer": "Certificate Revocation List＝証明書失効リスト。有効期間内に失効させた証明書のシリアル番号と失効日時の一覧。認証局が署名して公開する。", "explanation": "秘密鍵の漏えいなどで証明書を失効させる。有効期限が切れた証明書は載らない。", "createdAt": 1791810000093},
{"id": "sec-094", "section": "8.4", "type": "desc", "question": "OCSP とは？", "answer": "Online Certificate Status Protocol。証明書が失効していないかを、その場で問い合わせるプロトコル。CRL全体をダウンロードしなくてよい。", "explanation": "問い合わせに答えるサーバをOCSPレスポンダという。", "createdAt": 1791810000094},
{"id": "sec-095", "section": "8.5", "type": "desc", "question": "TLS とは？", "answer": "Transport Layer Security。インターネット上の通信を暗号化し、サーバ（必要ならクライアント）の認証と改ざんの検知を行うプロトコル。HTTPSなどで使う。", "explanation": "現在はTLS1.2・TLS1.3を使う。", "createdAt": 1791810000095},
{"id": "sec-096", "section": "8.5", "type": "desc", "question": "SSL（SSL/TLS）とは？", "answer": "SSL（Secure Sockets Layer）はTLSの前身のプロトコル。脆弱性のためSSLは使われなくなり、現在はTLSを使うが、慣例で「SSL」「SSL/TLS」と呼ぶことが多い。", "explanation": "", "createdAt": 1791810000096},
{"id": "sec-097", "section": "8.5", "type": "desc", "question": "ハンドシェイクとは？（TLS）", "answer": "通信を始める前にクライアントとサーバがやり取りし、使う暗号方式の決定、サーバ証明書による認証、共通鍵（セッション鍵）の共有を行う手順。", "explanation": "", "createdAt": 1791810000097},
{"id": "sec-098", "section": "8.5", "type": "desc", "question": "MAC とは？（メッセージ認証）", "answer": "Message Authentication Code＝メッセージ認証コード。メッセージと共通鍵から作る短い値で、メッセージの改ざんと送信者の正当性を確認する。", "explanation": "ハッシュ関数を使うものをHMACという。ネットワークのMACアドレス（Media Access Control）とは別物。", "createdAt": 1791810000098},
{"id": "sec-099", "section": "8.5", "type": "desc", "question": "サーバ認証とは？（TLS）", "answer": "クライアントが、接続先のサーバが本物であることをサーバ証明書で確認すること。偽のサイトへのなりすましを防ぐ。", "explanation": "", "createdAt": 1791810000099},
{"id": "sec-100", "section": "8.5", "type": "desc", "question": "クライアント認証とは？（TLS）", "answer": "サーバが、接続してきたクライアントが正当な利用者であることを、クライアント証明書で確認すること。", "explanation": "", "createdAt": 1791810000100},
{"id": "sec-101", "section": "8.5", "type": "desc", "question": "クライアント証明書とは？", "answer": "利用者や端末に発行されるデジタル証明書。TLSのクライアント認証やEAP-TLSで使い、許可した端末・利用者だけが接続できるようにする。", "explanation": "", "createdAt": 1791810000101},
{"id": "sec-102", "section": "8.5", "type": "desc", "question": "ドメイン認証型証明書（DV証明書）とは？", "answer": "Domain Validation。申請者がそのドメインを使う権利を持っていることだけを確認して発行されるサーバ証明書。発行が早く安いが、運営組織が実在するかは確認しない。", "explanation": "", "createdAt": 1791810000102},
{"id": "sec-103", "section": "8.5", "type": "desc", "question": "企業認証型証明書（OV証明書）とは？", "answer": "Organization Validation。ドメインを使う権利に加えて、運営組織が実在することを確認して発行されるサーバ証明書。", "explanation": "", "createdAt": 1791810000103},
{"id": "sec-104", "section": "8.5", "type": "desc", "question": "EV SSL証明書とは？", "answer": "Extended Validation＝拡張認証。厳格な審査基準（法的・物理的な実在の確認など）で組織の実在を確認して発行されるサーバ証明書。最も信頼性が高い。", "explanation": "", "createdAt": 1791810000104},
{"id": "sec-105", "section": "8.5", "type": "desc", "question": "DTLS とは？", "answer": "Datagram Transport Layer Security。UDPの上で使えるようにしたTLS。音声・映像の通信やIoTなど、リアルタイム性が大事な通信を暗号化する。", "explanation": "", "createdAt": 1791810000105},
{"id": "sec-106", "section": "8.5", "type": "desc", "question": "ファイアウォールとは？", "answer": "内部ネットワークと外部ネットワークの境界に置き、あらかじめ決めたルールに従って通信を許可・遮断する仕組み。", "explanation": "", "createdAt": 1791810000106},
{"id": "sec-107", "section": "8.5", "type": "desc", "question": "DMZ とは？", "answer": "DeMilitarized Zone＝非武装地帯。外部ネットワークと内部ネットワークの間に設けるネットワーク領域。Webサーバやメールサーバなど、外部に公開するサーバを置く。", "explanation": "公開サーバが乗っ取られても、内部ネットワークへ被害が広がるのを防げる。", "createdAt": 1791810000107},
{"id": "sec-108", "section": "8.5", "type": "desc", "question": "フィルタリングルールとは？", "answer": "ファイアウォールで、送信元・宛先のIPアドレスやポート番号、プロトコルなどの条件ごとに、通信を許可するか遮断するかを決めた規則。上から順に照合する。", "explanation": "最後に「どれにも当てはまらない通信はすべて遮断」とするのが基本。", "createdAt": 1791810000108},
{"id": "sec-109", "section": "8.5", "type": "desc", "question": "パケットフィルタリング型ファイアウォールとは？", "answer": "パケットのヘッダ情報（IPアドレス、ポート番号、プロトコル）を見て、通信を許可・遮断する方式。速いが、データの中身は検査しない。", "explanation": "", "createdAt": 1791810000109},
{"id": "sec-110", "section": "8.5", "type": "desc", "question": "アプリケーションゲートウェイ型ファイアウォールとは？", "answer": "アプリケーション層で通信を中継（プロキシ）し、データの中身まで検査する方式。細かい制御ができるが、処理が重い。", "explanation": "", "createdAt": 1791810000110},
{"id": "sec-111", "section": "8.5", "type": "desc", "question": "スタティックパケットフィルタリングとは？", "answer": "あらかじめ固定で設定したルールだけで、パケットを許可・遮断する方式。戻りの通信のために、ポートを常に開けておく必要がある。", "explanation": "", "createdAt": 1791810000111},
{"id": "sec-112", "section": "8.5", "type": "desc", "question": "ダイナミックパケットフィルタリングとは？", "answer": "内部から外部への通信が起きたときに、その戻りの通信だけを通すルールを動的に追加し、通信が終われば削除する方式。必要なときだけポートを開けるので安全性が高い。", "explanation": "通信の状態まで見て判断するステートフルインスペクションは、これをさらに発展させたもの。", "createdAt": 1791810000112},
{"id": "sec-113", "section": "8.5", "type": "desc", "question": "プロキシサーバとは？", "answer": "利用者の代わりにインターネット上のサーバへアクセスする代理サーバ。内部の端末を直接外部に接続させず、アクセス制御・キャッシュ・ログの記録を行う。", "explanation": "", "createdAt": 1791810000113},
{"id": "sec-114", "section": "8.5", "type": "desc", "question": "フォワードプロキシとは？", "answer": "内部ネットワークの利用者が外部のWebサイトへアクセスするときに、代わりに中継するプロキシ。一般に「プロキシサーバ」というとこれを指す。URLフィルタリングなどに使う。", "explanation": "", "createdAt": 1791810000114},
{"id": "sec-115", "section": "8.5", "type": "desc", "question": "WAF とは？", "answer": "Web Application Firewall＝Webアプリケーションファイアウォール。HTTPの通信内容を検査し、SQLインジェクションやクロスサイトスクリプティングなど、Webアプリケーションの脆弱性を狙う攻撃を検知・遮断する。", "explanation": "", "createdAt": 1791810000115},
{"id": "sec-116", "section": "8.5", "type": "desc", "question": "ホワイトリスト（許可リスト）とは？", "answer": "通信や実行を許可するものだけを登録した一覧。登録されていないものはすべて拒否する。安全性は高いが、登録の手間がかかる。", "explanation": "", "createdAt": 1791810000116},
{"id": "sec-117", "section": "8.5", "type": "desc", "question": "ブラックリスト（拒否リスト）とは？", "answer": "拒否するものを登録した一覧。登録されていないものは許可する。運用は楽だが、未知の攻撃は防げない。", "explanation": "", "createdAt": 1791810000117},
{"id": "sec-118", "section": "8.5", "type": "desc", "question": "TLSアクセラレータとは？", "answer": "TLSの暗号化・復号の処理を、Webサーバの代わりに専用の装置で行い、Webサーバの負荷を減らす機器。", "explanation": "復号した後の通信を、WAFやIDSで検査できるようにする目的でも使う。", "createdAt": 1791810000118},
{"id": "sec-119", "section": "8.5", "type": "desc", "question": "IDS とは？", "answer": "Intrusion Detection System＝侵入検知システム。ネットワークやサーバを監視し、不正アクセスや攻撃を検知して管理者に知らせる。通信の遮断はしない。", "explanation": "", "createdAt": 1791810000119},
{"id": "sec-120", "section": "8.5", "type": "desc", "question": "SIEM とは？", "answer": "Security Information and Event Management＝セキュリティ情報イベント管理。ファイアウォール、IDS、サーバなどのログを1か所に集めて関連づけて分析し、攻撃や異常をリアルタイムに検知・通知する仕組み。", "explanation": "", "createdAt": 1791810000120},
{"id": "sec-121", "section": "8.5", "type": "desc", "question": "NIDS とは？", "answer": "Network-based IDS＝ネットワーク型侵入検知システム。ネットワーク上を流れるパケットを監視して攻撃を検知する。", "explanation": "", "createdAt": 1791810000121},
{"id": "sec-122", "section": "8.5", "type": "desc", "question": "HIDS とは？", "answer": "Host-based IDS＝ホスト型侵入検知システム。サーバなどのホストに入れて、ログやファイルの改ざん、不審な動作を監視する。", "explanation": "", "createdAt": 1791810000122},
{"id": "sec-123", "section": "8.5", "type": "desc", "question": "IPS とは？", "answer": "Intrusion Prevention System＝侵入防止システム。不正な通信を検知するだけでなく、自動的に遮断する。", "explanation": "誤検知（フォールスポジティブ）すると、正常な通信まで止めてしまう。", "createdAt": 1791810000123},
{"id": "sec-124", "section": "8.5", "type": "desc", "question": "UTM とは？", "answer": "Unified Threat Management＝統合脅威管理。ファイアウォール、IDS/IPS、ウイルス対策、URLフィルタリングなど、複数のセキュリティ機能を1台にまとめた装置。", "explanation": "中小企業でも導入しやすい。", "createdAt": 1791810000124},
{"id": "sec-125", "section": "8.5", "type": "desc", "question": "EDR とは？", "answer": "Endpoint Detection and Response。PCやサーバ（エンドポイント）の動作を常に監視し、侵入された後の不審な動きを検知して、隔離や調査などの対応を助ける仕組み。", "explanation": "侵入を防ぐ従来のウイルス対策ソフトに対し、侵入された後の検知と対応に重点を置く。", "createdAt": 1791810000125},
{"id": "sec-126", "section": "8.5", "type": "desc", "question": "ハニーポットとは？", "answer": "わざと弱く見せたおとりのシステムを用意して攻撃者を誘い込み、攻撃の手口や動きを観察・記録する仕組み。", "explanation": "", "createdAt": 1791810000126},
{"id": "sec-127", "section": "8.5", "type": "desc", "question": "不正検知の方法にはどんなものがある？（IDS・IPS）", "answer": "既知の攻撃パターンと照合するシグネチャ方式（不正検出）と、正常な状態から外れたものを異常とみなすアノマリー方式（異常検出）がある。", "explanation": "", "createdAt": 1791810000127},
{"id": "sec-128", "section": "8.5", "type": "desc", "question": "シグネチャ方式とは？（不正検知）", "answer": "既知の攻撃の特徴（シグネチャ）と照合して検知する方式。誤検知は少ないが、未知の攻撃は検知できない。", "explanation": "", "createdAt": 1791810000128},
{"id": "sec-129", "section": "8.5", "type": "desc", "question": "アノマリー方式とは？（不正検知）", "answer": "正常な通信や動作を基準として決めておき、そこから外れたものを異常として検知する方式。未知の攻撃も検知できるが、誤検知が多くなりやすい。", "explanation": "", "createdAt": 1791810000129},
{"id": "sec-130", "section": "8.5", "type": "desc", "question": "フォールスポジティブとは？", "answer": "正常なものを、誤って攻撃（異常）と判定すること。誤検知。", "explanation": "", "createdAt": 1791810000130},
{"id": "sec-131", "section": "8.5", "type": "desc", "question": "フォールスネガティブとは？", "answer": "攻撃（異常）なのに正常と判定して、見逃すこと。検知漏れ。", "explanation": "", "createdAt": 1791810000131},
{"id": "sec-132", "section": "8.5", "type": "desc", "question": "VPN とは？", "answer": "Virtual Private Network＝仮想専用網。インターネットなどの公衆網の上に、暗号化や認証の技術で、仮想的な専用線を作る技術。", "explanation": "インターネットVPN（IPsec、SSL-VPN）と、通信事業者の閉じた網を使うIP-VPNがある。", "createdAt": 1791810000132},
{"id": "sec-133", "section": "8.5", "type": "desc", "question": "トランスポートモードとは？（IPsec）", "answer": "IPパケットのデータ部分だけを暗号化し、元のIPヘッダはそのまま使うモード。端末どうしが直接通信する場合に使う。", "explanation": "", "createdAt": 1791810000133},
{"id": "sec-134", "section": "8.5", "type": "desc", "question": "トンネルモードとは？（IPsec）", "answer": "元のIPパケット全体（ヘッダを含む）を暗号化し、新しいIPヘッダを付けて送るモード。拠点の間のVPN（VPN装置どうし）で使う。", "explanation": "", "createdAt": 1791810000134},
{"id": "sec-135", "section": "8.5", "type": "desc", "question": "IPsec とは？", "answer": "IP Security。ネットワーク層（IP）で暗号化と認証を行うプロトコル群。AH、ESP、IKEなどで構成され、VPNで使う。", "explanation": "ネットワーク層で動くので、上のアプリケーションはIPsecを意識しなくてよい。", "createdAt": 1791810000135},
{"id": "sec-136", "section": "8.5", "type": "desc", "question": "AH とは？（IPsec）", "answer": "Authentication Header＝認証ヘッダ。IPパケットの認証と改ざんの検知を行う。暗号化はしない。", "explanation": "", "createdAt": 1791810000136},
{"id": "sec-137", "section": "8.5", "type": "desc", "question": "ESP とは？（IPsec）", "answer": "Encapsulating Security Payload＝暗号ペイロード。IPパケットの暗号化と、認証・改ざんの検知を行う。", "explanation": "", "createdAt": 1791810000137},
{"id": "sec-138", "section": "8.5", "type": "desc", "question": "DH法とは？", "answer": "Diffie-Hellman（ディフィー・ヘルマン）鍵交換。盗聴されている通信路でも、互いの公開値をやり取りするだけで、第三者に知られずに同じ共通鍵を作れる方法。離散対数問題の難しさを利用する。", "explanation": "IKEやTLSの鍵交換で使われる。", "createdAt": 1791810000138},
{"id": "sec-139", "section": "8.5", "type": "desc", "question": "IKE とは？", "answer": "Internet Key Exchange。IPsecで使う暗号鍵を、DH法などを使って安全に交換・管理するプロトコル。", "explanation": "", "createdAt": 1791810000139},
{"id": "sec-140", "section": "8.5", "type": "desc", "question": "ペネトレーションテストとは？", "answer": "侵入テスト。攻撃者と同じ手口で実際にシステムへの侵入を試み、脆弱性やセキュリティ対策が有効かを確認する検査。", "explanation": "", "createdAt": 1791810000140},
{"id": "sec-141", "section": "8.5", "type": "desc", "question": "デジタルフォレンジックとは？", "answer": "不正アクセスや情報漏えいなどが起きたときに、コンピュータやログなどの電子的な記録を集めて保全・分析し、法的な証拠とする技術や手続き。", "explanation": "証拠を変えてしまわないよう、原本ではなく複製（コピー）を分析する。", "createdAt": 1791810000141},
{"id": "sec-142", "section": "8.5", "type": "desc", "question": "耐タンパ性とは？", "answer": "ICカードなどの装置の内部の情報を、外部から不正に読み取ったり書き換えたりすることが難しい性質。", "explanation": "無理に開けると内部のデータが消える仕組みなど。サイドチャネル攻撃への対策にもなる。", "createdAt": 1791810000142},
{"id": "sec-143", "section": "8.5", "type": "desc", "question": "カオスエンジニアリングとは？", "answer": "本番環境でわざと障害（サーバの停止、通信の遅れなど）を起こし、システムが耐えられるかを確かめながら、障害に強いシステムにしていく手法。", "explanation": "", "createdAt": 1791810000143},
{"id": "sec-144", "section": "8.6", "type": "desc", "question": "マルウェアとは？", "answer": "Malicious Software（悪意のあるソフトウェア）を縮めた造語。コンピュータウイルス、ワーム、トロイの木馬、ランサムウェアなど、不正な動作をするソフトウェアの総称。", "explanation": "", "createdAt": 1791810000144},
{"id": "sec-145", "section": "8.6", "type": "desc", "question": "コンピュータウイルス対策基準とは？", "answer": "経済産業省が定めた基準。ウイルスを「自己伝染機能、潜伏機能、発病機能のうち1つ以上を持つもの」と定義し、予防・発見・駆除・復旧の対策を示している。", "explanation": "", "createdAt": 1791810000145},
{"id": "sec-146", "section": "8.6", "type": "desc", "question": "自己伝染機能とは？（ウイルス）", "answer": "ウイルスが自分を他のプログラムにコピーしたり、システムの機能を使って他のシステムにコピーしたりして、感染を広げる機能。", "explanation": "", "createdAt": 1791810000146},
{"id": "sec-147", "section": "8.6", "type": "desc", "question": "潜伏機能とは？（ウイルス）", "answer": "発病する条件（特定の日時、処理の回数など）を記憶させて、条件を満たすまで症状を出さずに潜む機能。", "explanation": "", "createdAt": 1791810000147},
{"id": "sec-148", "section": "8.6", "type": "desc", "question": "発病機能とは？（ウイルス）", "answer": "プログラムやデータの破壊、おかしな画面の表示など、作った人の意図しない動作をする機能。", "explanation": "", "createdAt": 1791810000148},
{"id": "sec-149", "section": "8.6", "type": "desc", "question": "ワームとは？", "answer": "他のプログラムに寄生せず単独で動き、ネットワークを通じて自分自身を複製しながら感染を広げるマルウェア。", "explanation": "", "createdAt": 1791810000149},
{"id": "sec-150", "section": "8.6", "type": "desc", "question": "トロイの木馬とは？", "answer": "役に立つソフトウェアに見せかけて利用者にインストールさせ、裏で不正な動作をするマルウェア。自分を増やすことはしない。", "explanation": "", "createdAt": 1791810000150},
{"id": "sec-151", "section": "8.6", "type": "desc", "question": "ボットとは？", "answer": "感染したコンピュータを、外部の攻撃者（C&Cサーバ）からの指令で遠隔操作できるようにするマルウェア。", "explanation": "ボットに感染した多数のコンピュータの集まりをボットネットといい、DDoS攻撃やスパムメールの送信に使われる。", "createdAt": 1791810000151},
{"id": "sec-152", "section": "8.6", "type": "desc", "question": "バックドアとは？", "answer": "攻撃者が、正規の認証を通らずにいつでも侵入できるよう、システムに仕掛ける裏口。", "explanation": "", "createdAt": 1791810000152},
{"id": "sec-153", "section": "8.6", "type": "desc", "question": "ルートキットとは？", "answer": "攻撃者がシステムに侵入した後、侵入の跡を隠したり、管理者権限（root）を持ち続けたりするためのツールをまとめたもの。", "explanation": "", "createdAt": 1791810000153},
{"id": "sec-154", "section": "8.6", "type": "desc", "question": "ランサムウェアとは？", "answer": "感染したコンピュータのファイルを暗号化するなどして使えなくし、元に戻すことと引き換えに金銭（身代金）を要求するマルウェア。", "explanation": "近年は「盗んだデータを公開する」とも脅す二重脅迫型が多い。対策はネットワークから切り離したバックアップ。", "createdAt": 1791810000154},
{"id": "sec-155", "section": "8.6", "type": "desc", "question": "WORM とは？（ワームとの違いも）", "answer": "Write Once Read Many。一度だけ書き込めて、その後は書き換えも削除もできず、読み出しだけできる記録の方式・媒体。", "explanation": "ログの改ざん防止や、ランサムウェア対策のバックアップに使う。マルウェアのワーム（Worm）とは別物。", "createdAt": 1791810000155},
{"id": "sec-156", "section": "8.6", "type": "desc", "question": "キーロガーとは？", "answer": "キーボードで入力した内容を記録するソフトウェアや装置。パスワードなどを盗む目的で悪用される。", "explanation": "", "createdAt": 1791810000156},
{"id": "sec-157", "section": "8.6", "type": "desc", "question": "エクスプロイトキットとは？", "answer": "ソフトウェアの脆弱性を突く攻撃コード（エクスプロイト）を複数まとめたツール。Webサイトを見た人のPCの脆弱性を自動で調べて攻撃し、マルウェアに感染させるのに使われる。", "explanation": "", "createdAt": 1791810000157},
{"id": "sec-158", "section": "8.6", "type": "desc", "question": "マクロウイルスとは？", "answer": "WordやExcelなどのマクロ機能を悪用したウイルス。文書ファイルを開いたときに感染・発病する。", "explanation": "Emotetは、メールに添付した文書ファイルで広まった。", "createdAt": 1791810000158},
{"id": "sec-159", "section": "8.6", "type": "desc", "question": "偽セキュリティ対策ソフトとは？", "answer": "「ウイルスに感染しています」などと偽の警告を出して不安をあおり、有料の偽ソフトを買わせたり、マルウェアをインストールさせたりするソフトウェア。", "explanation": "", "createdAt": 1791810000159},
{"id": "sec-160", "section": "8.6", "type": "desc", "question": "シグネチャ（パターンファイル）とは？（マルウェア対策）", "answer": "既知のマルウェアの特徴的なコードなどを登録したデータ。ウイルス対策ソフトはこれと照合してマルウェアを見つける。定義ファイルともいう。", "explanation": "新しいマルウェアに対応するため、常に最新にしておく必要がある。", "createdAt": 1791810000160},
{"id": "sec-161", "section": "8.6", "type": "desc", "question": "セキュリティパッチとは？", "answer": "ソフトウェアの脆弱性を直すために、メーカーが提供するプログラム。修正プログラム。", "explanation": "", "createdAt": 1791810000161},
{"id": "sec-162", "section": "8.6", "type": "desc", "question": "ゼロデイ攻撃とは？", "answer": "脆弱性が見つかってから修正プログラム（パッチ）が提供されるまでの間に、その脆弱性を突いて行う攻撃。", "explanation": "", "createdAt": 1791810000162},
{"id": "sec-163", "section": "8.6", "type": "desc", "question": "パターンマッチング方式とは？（マルウェアの検出）", "answer": "検査する対象をシグネチャ（パターンファイル）と照合して、マルウェアを見つける方式。既知のマルウェアは確実に見つけられるが、未知のマルウェアや亜種は見つけられない。", "explanation": "", "createdAt": 1791810000163},
{"id": "sec-164", "section": "8.6", "type": "desc", "question": "マルウェアの検出方法にはどんなものがある？", "answer": "パターンマッチング方式、コンペア法、チェックサム法（インテグリティチェック法）、ビヘイビア法（動的ヒューリスティック法）、静的ヒューリスティック法、サンドボックスなど。", "explanation": "", "createdAt": 1791810000164},
{"id": "sec-165", "section": "8.6", "type": "desc", "question": "コンペア法とは？（マルウェアの検出）", "answer": "感染していない安全な原本と検査対象を比べ、違いがあれば感染を疑う方法。", "explanation": "", "createdAt": 1791810000165},
{"id": "sec-166", "section": "8.6", "type": "desc", "question": "チェックサム法・インテグリティチェック法とは？（マルウェアの検出）", "answer": "ファイルのチェックサムやハッシュ値をあらかじめ記録しておき、検査のときの値と比べて、ファイルが書き換えられていないか（感染していないか）を調べる方法。", "explanation": "", "createdAt": 1791810000166},
{"id": "sec-167", "section": "8.6", "type": "desc", "question": "サンドボックスとは？", "answer": "外部から切り離した仮想的な環境。不審なプログラムをその中で実際に動かし、動きを観察してマルウェアかどうかを判定する。中で実行しても本来のシステムに影響しない。", "explanation": "", "createdAt": 1791810000167},
{"id": "sec-168", "section": "8.6", "type": "desc", "question": "動的ヒューリスティック法とは？", "answer": "不審なプログラムをサンドボックスなどで実際に動かし、その動きからマルウェアかどうかを判定する方法。未知のマルウェアも見つけられる。", "explanation": "実行せずにコードを解析して判定するのは静的ヒューリスティック法。", "createdAt": 1791810000168},
{"id": "sec-169", "section": "8.6", "type": "desc", "question": "ポリモーフィック型マルウェアとは？", "answer": "感染するたびに自分のコードを暗号化したり形を変えたりして、異なる姿になるマルウェア。パターンマッチング方式では見つけにくい。", "explanation": "対策は、ビヘイビア法など動きから見つける方法。", "createdAt": 1791810000169},
{"id": "sec-170", "section": "8.6", "type": "desc", "question": "ビヘイビア法とは？", "answer": "プログラムを実行し、その動作（ファイルの書き換え、外部への通信など）を監視して、マルウェアに特有の不審な振る舞いを見つける方法。未知のマルウェアも見つけられる。", "explanation": "", "createdAt": 1791810000170},
{"id": "sec-171", "section": "8.6", "type": "desc", "question": "標的型攻撃メールとは？", "answer": "特定の組織や人を狙い、仕事に関係がありそうな件名・本文・差出人を装って、マルウェアを添付したり不正なURLを書いたりして送るメール。", "explanation": "", "createdAt": 1791810000171},
{"id": "sec-172", "section": "8.6", "type": "desc", "question": "パスワードリスト攻撃とは？", "answer": "他のサービスから流出したIDとパスワードの組み合わせ（リスト）を使って、別のサービスにログインを試みる攻撃。", "explanation": "パスワードの使い回しが原因で成功する。", "createdAt": 1791810000172},
{"id": "sec-173", "section": "8.6", "type": "desc", "question": "辞書攻撃とは？", "answer": "辞書に載っている単語や、よく使われるパスワードの一覧を順に試して、パスワードを破る攻撃。", "explanation": "", "createdAt": 1791810000173},
{"id": "sec-174", "section": "8.6", "type": "desc", "question": "ブルートフォース攻撃とは？", "answer": "総当たり攻撃。考えられるすべての文字の組み合わせを順に試して、パスワードを破る攻撃。", "explanation": "対策は、一定回数失敗したらアカウントをロックすること、長く複雑なパスワードにすること。", "createdAt": 1791810000174},
{"id": "sec-175", "section": "8.6", "type": "desc", "question": "類推攻撃とは？", "answer": "利用者の誕生日、名前、電話番号などの個人情報からパスワードを推測して試す攻撃。", "explanation": "", "createdAt": 1791810000175},
{"id": "sec-176", "section": "8.6", "type": "desc", "question": "リバースブルートフォース攻撃とは？", "answer": "パスワードを固定し（「123456」など）、IDの方を次々に変えてログインを試す攻撃。1つのIDで何度も失敗しないので、アカウントロックが働きにくい。", "explanation": "", "createdAt": 1791810000176},
{"id": "sec-177", "section": "8.6", "type": "desc", "question": "パスワードスプレー攻撃とは？", "answer": "よく使われるパスワードを1つ選び、多数のIDに対して、時間をあけて少しずつ試す攻撃。アカウントロックや検知を避けるのが目的。", "explanation": "リバースブルートフォース攻撃と似ているが、検知されないよう低い頻度で広く試す点が特徴。", "createdAt": 1791810000177},
{"id": "sec-178", "section": "8.6", "type": "desc", "question": "レインボーテーブル攻撃とは？", "answer": "パスワードの候補とそのハッシュ値の対応を効率よく記録した表（レインボーテーブル）を使い、盗んだハッシュ値から元のパスワードを短い時間で割り出す攻撃。", "explanation": "対策はソルトとストレッチング。", "createdAt": 1791810000178},
{"id": "sec-179", "section": "8.6", "type": "desc", "question": "ソルトとは？（パスワード）", "answer": "パスワードのハッシュ値を求める前に、利用者ごとに異なるランダムな文字列を加えること。また、その文字列。同じパスワードでも異なるハッシュ値になり、レインボーテーブル攻撃を防げる。", "explanation": "", "createdAt": 1791810000179},
{"id": "sec-180", "section": "8.6", "type": "desc", "question": "ストレッチングとは？（パスワード）", "answer": "ハッシュ関数の計算を何千回、何万回と繰り返してハッシュ値を求めること。1回の計算に時間がかかるため、総当たりで解読するのに膨大な時間がかかるようになる。", "explanation": "", "createdAt": 1791810000180},
{"id": "sec-181", "section": "8.6", "type": "desc", "question": "フットプリンティングとは？", "answer": "攻撃の前に、標的の組織やシステムについて、公開情報や調査（DNSの情報、IPアドレス、使っているソフトウェアなど）から情報を集めること。", "explanation": "", "createdAt": 1791810000181},
{"id": "sec-182", "section": "8.6", "type": "desc", "question": "サイバーキルチェーンとは？", "answer": "標的型攻撃の流れを7段階（偵察 → 武器化 → 配送 → 攻撃（エクスプロイト）→ インストール → 遠隔操作（C&C）→ 目的の実行）に分けたモデル。", "explanation": "どこかの段階で鎖を断ち切れば攻撃を防げる、という考え方で対策を立てる。", "createdAt": 1791810000182},
{"id": "sec-183", "section": "8.6", "type": "desc", "question": "ポートスキャンとは？", "answer": "標的のコンピュータのポートに順に通信を試し、どのポートが開いていて、どんなサービスが動いているかを調べること。攻撃の下調べとして行われる。", "explanation": "", "createdAt": 1791810000183},
{"id": "sec-184", "section": "8.6", "type": "desc", "question": "ステルススキャンとは？", "answer": "通信を最後まで確立しない（TCPの3ウェイハンドシェイクを完了させない）ことで、相手のログに記録されにくくしたポートスキャン。SYNスキャンやFINスキャンなど。", "explanation": "", "createdAt": 1791810000184},
{"id": "sec-185", "section": "8.6", "type": "desc", "question": "TCPスキャンとは？", "answer": "TCPの3ウェイハンドシェイクを最後まで行い、接続できればポートが開いていると判断するポートスキャン。TCPコネクトスキャン。確実だが、相手のログに残りやすい。", "explanation": "", "createdAt": 1791810000185},
{"id": "sec-186", "section": "8.6", "type": "desc", "question": "SYNスキャンとは？", "answer": "SYNパケットを送り、SYN/ACKが返ればポートが開いている、RSTが返れば閉じていると判断し、接続を確立せずに終わるポートスキャン。ハーフオープンスキャンともいう。", "explanation": "", "createdAt": 1791810000186},
{"id": "sec-187", "section": "8.6", "type": "desc", "question": "FINスキャンとは？", "answer": "FINパケットを送り、応答がなければポートが開いている、RSTが返れば閉じていると判断するポートスキャン。", "explanation": "", "createdAt": 1791810000187},
{"id": "sec-188", "section": "8.6", "type": "desc", "question": "UDPスキャンとは？", "answer": "UDPパケットを送り、ICMPのポート到達不能（port unreachable）が返ればポートは閉じている、応答がなければ開いている可能性があると判断するポートスキャン。", "explanation": "", "createdAt": 1791810000188},
{"id": "sec-189", "section": "8.6", "type": "desc", "question": "バッファオーバーフロー攻撃とは？", "answer": "プログラムが用意したメモリ領域（バッファ）の大きさを超えるデータを送り込み、あふれたデータで領域の外を書き換えて、不正なコードを実行させたりプログラムを止めたりする攻撃。", "explanation": "対策は、入力データの長さをチェックすること。", "createdAt": 1791810000189},
{"id": "sec-190", "section": "8.6", "type": "desc", "question": "ディレクトリトラバーサル（パストラバーサル）とは？", "answer": "ファイル名を指定する入力に「../」などを含め、本来アクセスできないディレクトリのファイルを読み出したり書き換えたりする攻撃。", "explanation": "", "createdAt": 1791810000190},
{"id": "sec-191", "section": "8.6", "type": "desc", "question": "SQLインジェクションとは？", "answer": "Webアプリケーションの入力欄に不正なSQL文の一部を入力し、データベースを不正に操作（情報の取得、改ざん、削除）する攻撃。", "explanation": "対策は、プレースホルダ（バインド機構）を使ってSQL文を組み立てること。", "createdAt": 1791810000191},
{"id": "sec-192", "section": "8.6", "type": "desc", "question": "クロスサイトスクリプティング（XSS）とは？", "answer": "Webアプリケーションの脆弱性を利用し、利用者のブラウザ上で攻撃者のスクリプトを実行させる攻撃。クッキーを盗んだり、偽の画面を表示したりするのに悪用される。", "explanation": "対策は、出力するときのエスケープ処理（「<」を「&lt;」に置き換えるなど）。", "createdAt": 1791810000192},
{"id": "sec-193", "section": "8.6", "type": "desc", "question": "フィッシングとは？", "answer": "実在する金融機関や企業を装ったメールなどで偽のWebサイトに誘導し、ID・パスワードやクレジットカード番号などを入力させて盗む詐欺。", "explanation": "", "createdAt": 1791810000193},
{"id": "sec-194", "section": "8.6", "type": "desc", "question": "スミッシングとは？", "answer": "SMS（ショートメッセージ）を使ったフィッシング。宅配便の不在通知や銀行などを装ったSMSで、偽のサイトに誘導する。", "explanation": "SMSとフィッシングを合わせた造語。", "createdAt": 1791810000194},
{"id": "sec-195", "section": "8.6", "type": "desc", "question": "SEOポイズニングとは？", "answer": "検索エンジン最適化（SEO）の手法を悪用し、特定の言葉で検索したときに悪意のあるWebサイトが検索結果の上位に出るようにして、利用者を誘導する攻撃。", "explanation": "", "createdAt": 1791810000195},
{"id": "sec-196", "section": "8.6", "type": "desc", "question": "リフレクション攻撃（リフレクタ攻撃）とは？", "answer": "送信元のIPアドレスを攻撃対象に偽って多数のサーバに問い合わせ、その応答を攻撃対象に集中させるDDoS攻撃。応答が問い合わせより大きくなる仕組みを使うものを増幅攻撃（アンプ攻撃）という。", "explanation": "DNSリフレクション（DNSアンプ）攻撃、NTP増幅攻撃など。", "createdAt": 1791810000196},
{"id": "sec-197", "section": "8.6", "type": "desc", "question": "NTP増幅攻撃とは？", "answer": "NTPサーバの、小さな問い合わせに大きな応答を返す機能（monlistなど）を悪用し、送信元を攻撃対象に偽って問い合わせることで、大量の応答を攻撃対象に送りつけるDDoS攻撃。", "explanation": "", "createdAt": 1791810000197},
{"id": "sec-198", "section": "8.6", "type": "desc", "question": "スマーフ攻撃とは？", "answer": "送信元を攻撃対象のIPアドレスに偽ったICMPエコー要求（ping）を、ネットワークのブロードキャストアドレスに送り、多数の端末からの応答を攻撃対象に集中させるDoS攻撃。", "explanation": "", "createdAt": 1791810000198},
{"id": "sec-199", "section": "8.6", "type": "desc", "question": "ICMP Flood攻撃とは？", "answer": "大量のICMPエコー要求（ping）を攻撃対象に送りつけ、回線や処理能力をあふれさせてサービスを妨害する攻撃。Ping Flood攻撃ともいう。", "explanation": "", "createdAt": 1791810000199},
{"id": "sec-200", "section": "8.6", "type": "desc", "question": "SYN Flood攻撃とは？", "answer": "TCPの接続要求（SYN）だけを大量に送り、相手にSYN/ACKを返させたまま接続を完了させないことで、サーバの接続待ちの資源を使い切らせるDoS攻撃。", "explanation": "", "createdAt": 1791810000200},
{"id": "sec-201", "section": "8.6", "type": "desc", "question": "標的型攻撃とは？", "answer": "特定の組織や個人を狙い、仕事に関係するメールを装うなどして、長い期間しつこく行う攻撃。機密情報を盗むのが主な目的。", "explanation": "長期間潜んで攻撃を続けるものをAPT（Advanced Persistent Threat）攻撃という。", "createdAt": 1791810000201},
{"id": "sec-202", "section": "8.6", "type": "desc", "question": "水飲み場型攻撃とは？", "answer": "標的の組織の人がよく見るWebサイトを改ざんしてマルウェアを仕込み、そのサイトを訪れた標的の人を感染させる攻撃。", "explanation": "特定のIPアドレスからのアクセスだけを攻撃することもある。", "createdAt": 1791810000202},
{"id": "sec-203", "section": "8.6", "type": "desc", "question": "やり取り型攻撃とは？", "answer": "標的型攻撃の一種。最初は無害なメールで問い合わせなどのやり取りを何度か行って信用させてから、マルウェア付きのメールを送る攻撃。", "explanation": "", "createdAt": 1791810000203},
{"id": "sec-204", "section": "8.6", "type": "desc", "question": "ビジネスメール詐欺（BEC）とは？", "answer": "Business E-mail Compromise。取引先や経営者を装った偽のメールを送り、偽の口座へお金を振り込ませる詐欺。", "explanation": "", "createdAt": 1791810000204},
{"id": "sec-205", "section": "8.6", "type": "desc", "question": "中間者攻撃（Man-in-the-middle攻撃）とは？", "answer": "通信する2者の間に攻撃者が割り込み、両方になりすまして通信を中継しながら、盗聴や改ざんを行う攻撃。", "explanation": "対策は、TLSのサーバ証明書の確認など、通信相手の認証。", "createdAt": 1791810000205},
{"id": "sec-206", "section": "8.6", "type": "desc", "question": "リプレイ攻撃とは？", "answer": "盗聴したログイン情報などの通信データを、そのまま送り直して正規の利用者になりすます攻撃。", "explanation": "対策は、ワンタイムパスワード、チャレンジレスポンス認証、タイムスタンプ。", "createdAt": 1791810000206},
{"id": "sec-207", "section": "8.6", "type": "desc", "question": "MITB攻撃（Man-in-the-browser攻撃）とは？", "answer": "マルウェアでブラウザを乗っ取り、利用者が正規のサイトで行う操作（ネットバンキングの送金など）を、利用者に気づかれないように書き換える攻撃。", "explanation": "正規のサイトとの通信なので、TLSやワンタイムパスワードだけでは防げない。送金内容も使って認証するトランザクション認証が対策。", "createdAt": 1791810000207},
{"id": "sec-208", "section": "8.6", "type": "desc", "question": "ドライブバイダウンロード攻撃とは？", "answer": "Webサイトを見ただけで、利用者が気づかないうちにマルウェアをダウンロード・実行させる攻撃。ブラウザやプラグインの脆弱性を突く。", "explanation": "", "createdAt": 1791810000208},
{"id": "sec-209", "section": "8.6", "type": "desc", "question": "ファイルレス攻撃とは？", "answer": "実行ファイルをディスクに保存せず、PowerShellなどOSの正規の機能を悪用して、メモリ上だけで不正な処理を行う攻撃。ファイルが残らないので、ウイルス対策ソフトで見つけにくい。", "explanation": "", "createdAt": 1791810000209},
{"id": "sec-210", "section": "8.6", "type": "desc", "question": "クリックジャッキングとは？", "answer": "正規のWebページの上に透明なページを重ね、利用者には見えているボタンを押したつもりにさせて、実際には透明なページのボタンを押させる攻撃。", "explanation": "対策は、X-Frame-Optionsヘッダなどで、他のサイトの枠（フレーム）の中に表示させないこと。", "createdAt": 1791810000210},
{"id": "sec-211", "section": "8.6", "type": "desc", "question": "クリプトジャッキングとは？", "answer": "他人のコンピュータの処理能力を無断で使い、暗号資産（仮想通貨）のマイニング（採掘）をさせる攻撃。", "explanation": "", "createdAt": 1791810000211},
{"id": "sec-212", "section": "8.6", "type": "desc", "question": "スパムメールとは？", "answer": "受け取る人の同意なく、広告や詐欺などの目的で大量に送りつけられる迷惑メール。", "explanation": "", "createdAt": 1791810000212},
{"id": "sec-213", "section": "8.6", "type": "desc", "question": "Adversarial Examples攻撃とは？", "answer": "敵対的サンプル。AIの画像認識などに、人間には分からない程度の細工（ノイズ）を加えたデータを入力し、AIに誤った判定をさせる攻撃。", "explanation": "", "createdAt": 1791810000213},
{"id": "sec-214", "section": "8.6", "type": "desc", "question": "ソーシャルエンジニアリングとは？", "answer": "人の心のすきや油断を突いて、パスワードなどの情報を盗み出す手口。電話で上司や管理者になりすます、肩越しにのぞき見る（ショルダーハッキング）、ごみ箱をあさる（トラッシング）など。", "explanation": "", "createdAt": 1791810000214},
{"id": "sec-215", "section": "8.6", "type": "desc", "question": "テンペスト技術とは？", "answer": "ディスプレイやケーブルなどから漏れる弱い電磁波を受信・解析して、表示内容や処理中のデータを盗み取る技術。", "explanation": "対策は、電磁波を遮る（シールドする）こと。", "createdAt": 1791810000215},
{"id": "sec-216", "section": "8.6", "type": "desc", "question": "サイドチャネル攻撃とは？", "answer": "暗号を処理する装置の消費電力、処理時間、電磁波などの物理的な情報を測って解析し、暗号鍵などの秘密の情報を推定する攻撃。", "explanation": "処理時間を使うものをタイミング攻撃、消費電力を使うものを電力解析攻撃という。対策は耐タンパ性を高めること。", "createdAt": 1791810000216},
{"id": "sec-217", "section": "8.6", "type": "desc", "question": "RLTrap とは？", "answer": "RLO（Right-to-Left Override）という、文字を右から左に表示させる特殊な制御文字を悪用して、実行ファイルの拡張子を偽ったマルウェアの名前。例：「photo[RLO]gpj.exe」が「photoexe.jpg」と表示され、画像ファイルに見える。", "explanation": "ファイル名の見た目だけで判断しない。拡張子が「.exe」などの実行ファイルは開かない。", "createdAt": 1791810000217},
{"id": "sec-218", "section": "8.6", "type": "desc", "question": "オープンリダイレクトとは？", "answer": "Webサイトの転送（リダイレクト）機能に脆弱性があり、任意の外部のURLへ転送できてしまうこと。正規のドメインのURLに見せかけて、フィッシングサイトへ誘導するのに悪用される。", "explanation": "", "createdAt": 1791810000218},
{"id": "sec-219", "section": "8.6", "type": "desc", "question": "ベイジアンフィルタとは？", "answer": "ベイズの定理を使い、受け取ったメールに含まれる単語の出現確率から、迷惑メールかどうかを判定するフィルタ。利用者が迷惑メールかどうかを教えるほど（学習するほど）精度が上がる。", "explanation": "", "createdAt": 1791810000219},
{"id": "sec-220", "section": "8.6", "type": "desc", "question": "ベイズの定理とは？", "answer": "事後確率 P(A|B) を、事前確率 P(A) と条件付き確率 P(B|A) から求める定理。P(A|B) = P(B|A) × P(A) ÷ P(B)。結果（B）から原因（A）の確率を求めるのに使う。", "explanation": "", "createdAt": 1791810000220},
{"id": "sec-221", "section": "8.6", "type": "desc", "question": "DoS攻撃（サービス妨害攻撃）とは？", "answer": "Denial of Service。大量のデータや要求を送りつけてサーバやネットワークに大きな負荷をかけ、サービスを提供できなくする攻撃。", "explanation": "", "createdAt": 1791810000221},
{"id": "sec-222", "section": "8.6", "type": "desc", "question": "DDoS攻撃（分散型サービス妨害攻撃）とは？", "answer": "Distributed Denial of Service。ボットネットなどの多数のコンピュータから、一斉にDoS攻撃を行う攻撃。送信元が多いので、特定の送信元を遮断するだけでは防ぎにくい。", "explanation": "", "createdAt": 1791810000222},
{"id": "sec-223", "section": "8.6", "type": "desc", "question": "マルチベクトル型DDoS攻撃とは？", "answer": "複数の種類のDDoS攻撃（SYN Flood、UDP Flood、HTTP Floodなど）を組み合わせたり切り替えたりして同時に行う攻撃。1つの対策だけでは防ぎにくい。", "explanation": "", "createdAt": 1791810000223},
{"id": "sec-224", "section": "8.7", "type": "desc", "question": "ゾーニングとは？（物理的セキュリティ）", "answer": "オフィスなどを、扱う情報の重要度に応じて区域（一般エリア、執務エリア、サーバ室など）に分け、区域ごとに入退室を制限すること。", "explanation": "", "createdAt": 1791810000224},
{"id": "sec-225", "section": "8.7", "type": "desc", "question": "クリアデスクとは？", "answer": "席を離れるときや帰るときに、机の上に書類や記憶媒体を出しっぱなしにせず、鍵のかかる場所にしまうこと。", "explanation": "", "createdAt": 1791810000225},
{"id": "sec-226", "section": "8.7", "type": "desc", "question": "クリアスクリーンとは？", "answer": "席を離れるときにPCの画面をロックするなどして、画面の情報を他人に見られないようにすること。", "explanation": "", "createdAt": 1791810000226},
{"id": "sec-227", "section": "8.7", "type": "desc", "question": "アンチパスバックとは？", "answer": "入室の記録がない人は退室できない（退室の記録がない人は再び入室できない）ようにする入退室管理の仕組み。共連れ（他人の後について入ること）を防ぐ。", "explanation": "", "createdAt": 1791810000227},
{"id": "sec-228", "section": "8.7", "type": "desc", "question": "インターロックとは？（入退室管理）", "answer": "2つの扉があるとき、一方の扉が閉まっていないと、もう一方の扉が開かない仕組み。1人ずつしか通れないようにして、共連れを防ぐ。", "explanation": "条件がそろわないと動作しないようにして安全を守る仕組み全般も、インターロックという。", "createdAt": 1791810000228},
{"id": "sec-229", "section": "8.7", "type": "desc", "question": "TPMOR とは？", "answer": "Two Person Minimum Occupancy Rule＝2人最小在室ルール。サーバ室などの重要な部屋には、常に2人以上がいるようにし、1人だけで作業できないようにするルール。互いに見張ることで不正を防ぐ。", "explanation": "最後の1人が残らないよう、入退室を制御する。", "createdAt": 1791810000229},
{"id": "sec-230", "section": "8.7", "type": "desc", "question": "シャドーITとは？", "answer": "会社の情報システム部門が把握・許可していないIT機器やクラウドサービスを、従業員が仕事で勝手に使うこと。情報漏えいの原因になる。", "explanation": "", "createdAt": 1791810000230},
{"id": "sec-231", "section": "8.7", "type": "desc", "question": "不正のトライアングルとは？", "answer": "不正は「動機（プレッシャー）」「機会」「正当化」の3つがそろったときに起こるという理論。米国の犯罪学者クレッシーが唱えた。", "explanation": "組織として取り組みやすい対策は、機会をなくすこと（アクセスの制限、監視など）。", "createdAt": 1791810000231},
{"id": "sec-232", "section": "8.7", "type": "desc", "question": "リスクマネジメントとは？", "answer": "リスクについて、組織を指揮・管理するための調整された活動。リスクアセスメント（特定・分析・評価）とリスク対応を行い、継続的に監視・見直しをする。", "explanation": "", "createdAt": 1791810000232},
{"id": "sec-233", "section": "8.7", "type": "desc", "question": "リスクアセスメントとは？", "answer": "リスク特定、リスク分析、リスク評価を行うプロセス全体。", "explanation": "", "createdAt": 1791810000233},
{"id": "sec-234", "section": "8.7", "type": "desc", "question": "JIS Q 27000:2019 とは？", "answer": "ISMS（情報セキュリティマネジメントシステム）で使う用語とその定義を定めた日本産業規格。ISO/IEC 27000 を翻訳した規格。", "explanation": "", "createdAt": 1791810000234},
{"id": "sec-235", "section": "8.7", "type": "desc", "question": "リスク特定とは？", "answer": "リスクを見つけ出し、認識し、記述するプロセス。どの情報資産に、どんな脅威・脆弱性があるかを洗い出す。", "explanation": "", "createdAt": 1791810000235},
{"id": "sec-236", "section": "8.7", "type": "desc", "question": "リスク分析とは？", "answer": "リスクの性質を理解し、リスクレベルを決めるプロセス。起こりやすさ（頻度）と、起きたときの影響の大きさ（結果）を分析する。", "explanation": "", "createdAt": 1791810000236},
{"id": "sec-237", "section": "8.7", "type": "desc", "question": "リスク評価とは？", "answer": "リスク分析の結果をリスク基準と比べて、リスクとその大きさが受け入れられるかどうかを決め、対応の優先順位を決めるプロセス。", "explanation": "", "createdAt": 1791810000237},
{"id": "sec-238", "section": "8.7", "type": "desc", "question": "純粋リスクとは？", "answer": "損失だけが起きるリスク。利益が出る可能性はない。例：火災、地震、盗難、情報漏えい。", "explanation": "情報セキュリティで扱うのは主に純粋リスク。", "createdAt": 1791810000238},
{"id": "sec-239", "section": "8.7", "type": "desc", "question": "投機的リスクとは？", "answer": "損失が出る可能性と、利益が出る可能性の両方があるリスク。例：新規事業への投資、為替の変動。", "explanation": "", "createdAt": 1791810000239},
{"id": "sec-240", "section": "8.7", "type": "desc", "question": "リスクレベルとは？", "answer": "起きたときの影響の大きさ（結果）と、その起こりやすさの組み合わせで表すリスクの大きさ。", "explanation": "", "createdAt": 1791810000240},
{"id": "sec-241", "section": "8.7", "type": "desc", "question": "リスク対応とは？", "answer": "リスクを修正するプロセス。リスク回避、リスク低減、リスク移転（共有）、リスク保有の中から対応を選んで実施する。", "explanation": "", "createdAt": 1791810000241},
{"id": "sec-242", "section": "8.7", "type": "desc", "question": "定量的評価とは？（リスク）", "answer": "リスクを金額などの数値で評価する方法。例：年間予想損失額 ＝ 1回の損失額 × 年間の発生頻度。客観的に比べやすいが、数値にするのが難しい場合がある。", "explanation": "", "createdAt": 1791810000242},
{"id": "sec-243", "section": "8.7", "type": "desc", "question": "定性的評価とは？（リスク）", "answer": "リスクを「高・中・低」などの段階や点数で評価する方法。数値にしにくいリスクも評価できるが、評価する人の主観が入りやすい。", "explanation": "", "createdAt": 1791810000243},
{"id": "sec-244", "section": "8.7", "type": "desc", "question": "リスク回避とは？", "answer": "リスクの原因となる活動そのものをやめたり、別の方法に変えたりして、リスクがない状態にすること。例：個人情報を扱う業務をやめる。", "explanation": "", "createdAt": 1791810000244},
{"id": "sec-245", "section": "8.7", "type": "desc", "question": "リスク低減（リスク軽減）とは？", "answer": "対策を行って、リスクが起こる可能性や、起きたときの影響を小さくすること。例：ウイルス対策ソフトの導入、バックアップ。", "explanation": "", "createdAt": 1791810000245},
{"id": "sec-246", "section": "8.7", "type": "desc", "question": "リスク移転（リスク転嫁）とは？", "answer": "保険をかけたり業務を外部に委託したりして、リスクを他者に移す（他者と分け合う）こと。", "explanation": "JIS Q 31000 などではリスク共有と呼ぶ。", "createdAt": 1791810000246},
{"id": "sec-247", "section": "8.7", "type": "desc", "question": "リスク保有（リスク受容）とは？", "answer": "リスクが小さい場合や、対策の費用に見合わない場合に、特に対策をせず、リスクをそのまま受け入れること。", "explanation": "", "createdAt": 1791810000247},
{"id": "sec-248", "section": "8.7", "type": "desc", "question": "予防保守とは？", "answer": "故障が起きる前に、定期的に点検や部品交換を行い、故障を未然に防ぐ保守。", "explanation": "リスクコントロール（損失予防）の手段の一つ。", "createdAt": 1791810000248},
{"id": "sec-249", "section": "8.7", "type": "desc", "question": "損失予防とは？", "answer": "リスクコントロールの一つ。損失が起きる可能性（頻度）を下げる対策。例：防火設備、教育。", "explanation": "", "createdAt": 1791810000249},
{"id": "sec-250", "section": "8.7", "type": "desc", "question": "損失軽減とは？", "answer": "リスクコントロールの一つ。損失が起きたときの影響（規模）を小さくする対策。例：スプリンクラー、バックアップ。", "explanation": "", "createdAt": 1791810000250},
{"id": "sec-251", "section": "8.7", "type": "desc", "question": "リスク分散とは？", "answer": "拠点やシステム、取引先などを複数に分けて、1か所で損失が起きても全体への影響を小さくすること。", "explanation": "", "createdAt": 1791810000251},
{"id": "sec-252", "section": "8.7", "type": "desc", "question": "リスク集約とは？", "answer": "分散しているリスクを1か所にまとめて管理すること。例：データをデータセンターにまとめて、重点的に守る。", "explanation": "", "createdAt": 1791810000252},
{"id": "sec-253", "section": "8.7", "type": "desc", "question": "リスクファイナンスとは？", "answer": "損失が起きたときの費用を、お金の面で手当てする方法。保険をかける（リスク移転）、引当金を積み立てる（リスク保有）など。", "explanation": "損失が起きるのを防いだり広がるのを抑えたりする対策は、リスクコントロールという。", "createdAt": 1791810000253},
{"id": "sec-254", "section": "8.7", "type": "desc", "question": "ISO/IEC 15408 とは？", "answer": "IT製品やシステムのセキュリティ機能と品質を評価・認証するための国際規格。情報セキュリティ国際評価基準（CC）。日本の規格では JIS X 5070。", "explanation": "", "createdAt": 1791810000254},
{"id": "sec-255", "section": "8.7", "type": "desc", "question": "JIS X 5070 とは？", "answer": "ISO/IEC 15408 を日本産業規格にしたもの。IT製品のセキュリティを評価する基準。", "explanation": "", "createdAt": 1791810000255},
{"id": "sec-256", "section": "8.7", "type": "desc", "question": "情報セキュリティ国際評価基準（CC: Common Criteria）とは？", "answer": "ISO/IEC 15408 の通称。IT製品のセキュリティ機能が正しく作られているかを、第三者が評価するための基準。", "explanation": "評価の保証レベルを EAL（1〜7）で表す。", "createdAt": 1791810000256},
{"id": "sec-257", "section": "8.7", "type": "desc", "question": "ISMS とは？", "answer": "Information Security Management System＝情報セキュリティマネジメントシステム。組織が情報セキュリティを管理するための仕組み。PDCAサイクルで継続的に改善する。", "explanation": "", "createdAt": 1791810000257},
{"id": "sec-258", "section": "8.7", "type": "desc", "question": "JIS Q 27001 とは？", "answer": "ISMSの要求事項（ISMSを作り、実施し、維持し、改善するために必要なこと）を定めた日本産業規格。ISMS認証の審査基準になる。ISO/IEC 27001 を翻訳した規格。", "explanation": "", "createdAt": 1791810000258},
{"id": "sec-259", "section": "8.7", "type": "desc", "question": "JIS Q 27002 とは？", "answer": "情報セキュリティの管理策を実践するための規範（具体的な管理策のガイドライン）を定めた日本産業規格。ISO/IEC 27002 を翻訳した規格。", "explanation": "", "createdAt": 1791810000259},
{"id": "sec-260", "section": "8.7", "type": "desc", "question": "ISMAP とは？", "answer": "Information system Security Management and Assessment Program＝政府情報システムのためのセキュリティ評価制度。政府が求めるセキュリティの要求を満たすクラウドサービスを評価・登録する制度。", "explanation": "政府機関は、ISMAPに登録されたクラウドサービスから調達するのが原則。", "createdAt": 1791810000260},
{"id": "sec-261", "section": "8.7", "type": "desc", "question": "ISMS適合性評価制度とは？", "answer": "組織のISMSが JIS Q 27001 に合っているかを、第三者の認証機関が審査して認証する制度。", "explanation": "", "createdAt": 1791810000261},
{"id": "sec-262", "section": "8.7", "type": "desc", "question": "CRYPTREC暗号リストとは？", "answer": "CRYPTREC（Cryptography Research and Evaluation Committees）が安全性と実装性能を評価した暗号技術のリスト。電子政府推奨暗号リスト、推奨候補暗号リスト、運用監視暗号リストの3つからなる。", "explanation": "CRYPTRECは、デジタル庁・総務省・経済産業省などが運営する。", "createdAt": 1791810000262},
{"id": "sec-263", "section": "8.7", "type": "desc", "question": "電子政府推奨暗号リストとは？", "answer": "CRYPTREC暗号リストの一つ。安全性と実装性能が確認され、市場での利用実績も十分で、利用を推奨する暗号技術の一覧。", "explanation": "", "createdAt": 1791810000263},
{"id": "sec-264", "section": "8.7", "type": "desc", "question": "推奨候補暗号リストとは？", "answer": "CRYPTREC暗号リストの一つ。安全性と実装性能は確認されているが、利用実績が十分でないなどの理由で、今後推奨暗号になる可能性がある暗号技術の一覧。", "explanation": "", "createdAt": 1791810000264},
{"id": "sec-265", "section": "8.7", "type": "desc", "question": "運用監視暗号リストとは？", "answer": "CRYPTREC暗号リストの一つ。解読される危険性が高まっていて推奨はしないが、互換性を保つために、当面は使い続けることを認める暗号技術の一覧。", "explanation": "", "createdAt": 1791810000265},
{"id": "sec-266", "section": "8.7", "type": "desc", "question": "CSIRT とは？", "answer": "Computer Security Incident Response Team。セキュリティインシデントが起きたときに、報告を受け付け、調査・対応・再発防止を行う組織内のチーム。", "explanation": "", "createdAt": 1791810000266},
{"id": "sec-267", "section": "8.7", "type": "desc", "question": "JPCERT/CC とは？", "answer": "JPCERTコーディネーションセンター（Japan Computer Emergency Response Team Coordination Center）。日本国内のインシデントの報告受付や対応の支援、海外のCSIRTとの調整を行う組織。特定の政府機関や企業から独立している。", "explanation": "", "createdAt": 1791810000267},
{"id": "sec-268", "section": "8.7", "type": "desc", "question": "PSIRT とは？", "answer": "Product Security Incident Response Team。自社が開発・提供する製品やサービスの脆弱性に対応する組織。", "explanation": "", "createdAt": 1791810000268},
{"id": "sec-269", "section": "8.7", "type": "desc", "question": "SIM3 とは？", "answer": "Security Incident Management Maturity Model。CSIRTの組織としての成熟度を評価するためのモデル。", "explanation": "", "createdAt": 1791810000269},
{"id": "sec-270", "section": "8.7", "type": "desc", "question": "JVN とは？", "answer": "Japan Vulnerability Notes。日本で使われているソフトウェアなどの脆弱性の情報と、その対策の情報を提供するポータルサイト。JPCERT/CCとIPAが共同で運営する。", "explanation": "", "createdAt": 1791810000270},
{"id": "sec-271", "section": "8.7", "type": "desc", "question": "J-CRAT とは？", "answer": "サイバーレスキュー隊（Cyber Rescue and Advice Team against targeted attack of Japan）。IPAが設けた、標的型サイバー攻撃の被害を受けた組織を支援する組織。", "explanation": "", "createdAt": 1791810000271},
{"id": "sec-272", "section": "8.7", "type": "desc", "question": "CVSS とは？", "answer": "Common Vulnerability Scoring System＝共通脆弱性評価システム。脆弱性の深刻度を、ベンダに依存しない共通の基準で 0.0〜10.0 の数値で評価する手法。", "explanation": "v3.1では基本評価基準・現状評価基準・環境評価基準の3つで評価する（v4.0では基本・脅威・環境・補足）。", "createdAt": 1791810000272},
{"id": "sec-273", "section": "8.7", "type": "desc", "question": "CCE とは？", "answer": "Common Configuration Enumeration＝共通セキュリティ設定一覧。ソフトウェアのセキュリティに関する設定項目に、共通の識別番号を付けたもの。", "explanation": "", "createdAt": 1791810000273},
{"id": "sec-274", "section": "8.7", "type": "desc", "question": "CVE とは？", "answer": "Common Vulnerabilities and Exposures＝共通脆弱性識別子。個々の脆弱性に付ける世界共通の識別番号（例：CVE-2024-12345）。", "explanation": "", "createdAt": 1791810000274},
{"id": "sec-275", "section": "8.7", "type": "desc", "question": "CWE とは？", "answer": "Common Weakness Enumeration＝共通脆弱性タイプ一覧。SQLインジェクションやバッファオーバーフローなど、脆弱性の種類（タイプ）を分類して識別番号を付けたもの。", "explanation": "", "createdAt": 1791810000275}
];
